// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.accessibilityimport timber.log.Timberimport kotlinx.coroutines.sync.Muteximport kotlinx.coroutines.sync.withLock/** * NOUS — Low Vision Mode (Module 6 v4 — Step 6.6). * * Accessibility mode for partially sighted users (partial sight, elderly) — * provides high-contrast UI, large text, zoom assist, and display preferences. * * Per strategy v4 §"Issue 13: Missing Accessibility — Low Vision Mode": * * > "v3 targets blind users (screen reader), but doesn't mention low vision * > users (partial sight, elderly). They need high-contrast UI, large text, zoom." * * ## Features * *  - **High-contrast themes** — Black/Yellow (max contrast), Black/White, White/Black *  - **Font size scaling** — 1.0x (default), 1.5x, 2.0x (system-wide via Module 10) *  - **Vision output** — TTS + LARGE TEXT on screen (not just TTS) *  - **Camera zoom assist** — 2x digital zoom on tap *  - **Document scan auto-rotate** — landscape for larger text *  - **Screen overlay** — high-contrast text overlay for vision results * * ## Configuration * * User configures Low Vision Mode in Settings → Accessibility → Low Vision Mode. * Settings are persisted in DataStore (Module 1) and applied system-wide via * Module 10's DisplayService. * * ## Testability * * [LowVisionMode] is a pure data class + configuration manager. Display * rendering is delegated to Module 10 (System) + Module 16 (UI). * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Issue 13: Low Vision Mode</a> */class LowVisionMode(    private val settingsStore: LowVisionSettingsStore = InMemoryLowVisionSettingsStore(),) {    /**     * Enable Low Vision Mode with the specified configuration.     *     * @param config the Low Vision configuration.     */    suspend fun enable(config: LowVisionConfig = LowVisionConfig.DEFAULT) {        settingsStore.saveConfig(config.copy(enabled = true))        Timber.tag(TAG).i("Low Vision Mode enabled: $config.")    }    /** Disable Low Vision Mode. */    suspend fun disable() {        val current = settingsStore.getConfig()        settingsStore.saveConfig(current.copy(enabled = false))        Timber.tag(TAG).i("Low Vision Mode disabled.")    }    /** True if Low Vision Mode is currently enabled. */    suspend fun isEnabled(): Boolean = settingsStore.getConfig().enabled    /**     * Get the current Low Vision configuration.     */    suspend fun getConfig(): LowVisionConfig = settingsStore.getConfig()    /**     * Update a specific configuration field (partial update).     */    suspend fun updateConfig(update: LowVisionConfigUpdate): LowVisionConfig {        val current = settingsStore.getConfig()        val updated = current.copy(            enabled = update.enabled ?: current.enabled,            theme = update.theme ?: current.theme,            fontScale = update.fontScale ?: current.fontScale,            cameraZoom = update.cameraZoom ?: current.cameraZoom,            autoRotateLandscape = update.autoRotateLandscape ?: current.autoRotateLandscape,            showTextOverlay = update.showTextOverlay ?: current.showTextOverlay,            overlayPosition = update.overlayPosition ?: current.overlayPosition,            overlayDurationMs = update.overlayDurationMs ?: current.overlayDurationMs,            highContrastButtons = update.highContrastButtons ?: current.highContrastButtons,            boldText = update.boldText ?: current.boldText,            reduceMotion = update.reduceMotion ?: current.reduceMotion,        )        settingsStore.saveConfig(updated)        Timber.tag(TAG).i("Low Vision config updated: $updated.")        return updated    }    /**     * Format a vision result for Low Vision display (large text + high contrast).     *     * @param text the vision result text.     * @return formatted text with Low Vision markers (for UI rendering).     */    fun formatForDisplay(text: String): LowVisionDisplayText {        val config = settingsStore.getConfigSync()        val fontSize = when (config.fontScale) {            FontScale.NORMAL -> 16f            FontScale.LARGE -> 24f            FontScale.EXTRA_LARGE -> 32f        }        val colors = when (config.theme) {            HighContrastTheme.BLACK_YELLOW -> ColorPair(background = "#000000", foreground = "#FFFF00")            HighContrastTheme.BLACK_WHITE -> ColorPair(background = "#000000", foreground = "#FFFFFF")            HighContrastTheme.WHITE_BLACK -> ColorPair(background = "#FFFFFF", foreground = "#000000")            HighContrastTheme.YELLOW_BLACK -> ColorPair(background = "#FFFF00", foreground = "#000000")        }        return LowVisionDisplayText(            text = text,            fontSize = fontSize,            isBold = config.boldText,            backgroundColor = colors.background,            foregroundColor = colors.foreground,            overlayPosition = config.overlayPosition,            displayDurationMs = config.overlayDurationMs,        )    }    /**     * Get the camera zoom factor for Low Vision (2x digital zoom on tap).     */    fun getCameraZoomFactor(): Float = settingsStore.getConfigSync().cameraZoom.zoomFactor    private companion object {        private const val TAG = "LowVisionMode"    }}// ──────────────────────────────────────────────────────────────────────────/** Low Vision Mode configuration. */data class LowVisionConfig(    val enabled: Boolean = false,    val theme: HighContrastTheme = HighContrastTheme.BLACK_YELLOW,    val fontScale: FontScale = FontScale.LARGE,    val cameraZoom: CameraZoom = CameraZoom.X2,    val autoRotateLandscape: Boolean = true,    val showTextOverlay: Boolean = true,    val overlayPosition: OverlayPosition = OverlayPosition.BOTTOM,    val overlayDurationMs: Long = 5000L,    val highContrastButtons: Boolean = true,    val boldText: Boolean = true,    val reduceMotion: Boolean = false,) {    companion object {        /** Default configuration — black/yellow theme, large text, 2x zoom. */        val DEFAULT = LowVisionConfig()        /** Mild low vision — large text only, no high contrast. */        val MILD = LowVisionConfig(            theme = HighContrastTheme.BLACK_WHITE,            fontScale = FontScale.LARGE,            cameraZoom = CameraZoom.OFF,            highContrastButtons = false,        )        /** Severe low vision — max contrast, extra-large text, 2x zoom. */        val SEVERE = LowVisionConfig(            theme = HighContrastTheme.BLACK_YELLOW,            fontScale = FontScale.EXTRA_LARGE,            cameraZoom = CameraZoom.X2,            boldText = true,            reduceMotion = true,        )    }}/** Partial update for [LowVisionConfig]. */data class LowVisionConfigUpdate(    val enabled: Boolean? = null,    val theme: HighContrastTheme? = null,    val fontScale: FontScale? = null,    val cameraZoom: CameraZoom? = null,    val autoRotateLandscape: Boolean? = null,    val showTextOverlay: Boolean? = null,    val overlayPosition: OverlayPosition? = null,    val overlayDurationMs: Long? = null,    val highContrastButtons: Boolean? = null,    val boldText: Boolean? = null,    val reduceMotion: Boolean? = null,)/** High-contrast theme options. */enum class HighContrastTheme(val displayName: String, val backgroundColor: String, val foregroundColor: String) {    BLACK_YELLOW("Black on Yellow", "#000000", "#FFFF00"),    BLACK_WHITE("Black on White", "#000000", "#FFFFFF"),    WHITE_BLACK("White on Black", "#FFFFFF", "#000000"),    YELLOW_BLACK("Yellow on Black", "#FFFF00", "#000000"),}/** Font size scale options. */enum class FontScale(val displayName: String, val scale: Float) {    NORMAL("Normal (1.0x)", 1.0f),    LARGE("Large (1.5x)", 1.5f),    EXTRA_LARGE("Extra Large (2.0x)", 2.0f),}/** Camera zoom options for Low Vision assist. */enum class CameraZoom(val displayName: String, val zoomFactor: Float) {    OFF("No Zoom (1.0x)", 1.0f),    X2("2x Zoom", 2.0f),    X4("4x Zoom", 4.0f),}/** Screen overlay position for vision result text. */enum class OverlayPosition(val displayName: String) {    TOP("Top of Screen"),    CENTER("Center of Screen"),    BOTTOM("Bottom of Screen"),}/** A color pair (background + foreground). */data class ColorPair(val background: String, val foreground: String)/** Formatted text for Low Vision display. */data class LowVisionDisplayText(    val text: String,    val fontSize: Float,    val isBold: Boolean,    val backgroundColor: String,    val foregroundColor: String,    val overlayPosition: OverlayPosition,    val displayDurationMs: Long,)// ──────────────────────────────────────────────────────────────────────────/** * Settings store interface — abstracts DataStore (Module 1). * * Production: [DataStoreLowVisionSettingsStore] wraps Preferences DataStore. * Tests: [InMemoryLowVisionSettingsStore] uses in-memory state. */interface LowVisionSettingsStore {    suspend fun getConfig(): LowVisionConfig    fun getConfigSync(): LowVisionConfig    suspend fun saveConfig(config: LowVisionConfig)}/** * In-memory [LowVisionSettingsStore] for tests + default. */class InMemoryLowVisionSettingsStore(    private var config: LowVisionConfig = LowVisionConfig(enabled = false),) : LowVisionSettingsStore {    private val mutex = Mutex()    override suspend fun getConfig(): LowVisionConfig = mutex.withLock { config }    @Synchronized    override fun getConfigSync(): LowVisionConfig = config    override suspend fun saveConfig(config: LowVisionConfig) {        mutex.withLock { this.config = config }    }}